dtsPropsFor.Button:
/** Visual style. Default: 'primary'. */
  variant?: 'primary' | 'secondary' | 'outline' | 'ghost' | 'destructive';
  /** 'default' is the 48px minimum touch target; 'icon' is a 48x48 square. Default: 'default'. */
  size?: 'default' | 'lg' | 'icon';
  /** Stretch to the full width of the container. Default: false. */
  block?: boolean;
  /** Defaults to 'button' - pass 'submit' explicitly inside a form. */
  type?: 'button' | 'submit' | 'reset';
  disabled?: boolean;
  onClick?: React.MouseEventHandler<HTMLButtonElement>;
  children?: React.ReactNode;
  className?: string;

dtsPropsFor.Field:
/** Rendered as a <label> bound to the control by id. */
  label: string;
  /** Small muted helper text under the control. */
  hint?: string;
  /** Render prop: receives the generated id to hang on the control. */
  children: (id: string) => React.ReactNode;
  className?: string;

dtsPropsFor.Input:
type?: string;
  value?: string | number;
  defaultValue?: string | number;
  placeholder?: string;
  disabled?: boolean;
  inputMode?: 'text' | 'numeric' | 'decimal' | 'tel' | 'email' | 'search' | 'url';
  onChange?: React.ChangeEventHandler<HTMLInputElement>;
  id?: string;
  className?: string;

dtsPropsFor.Textarea:
value?: string;
  defaultValue?: string;
  placeholder?: string;
  rows?: number;
  disabled?: boolean;
  onChange?: React.ChangeEventHandler<HTMLTextAreaElement>;
  id?: string;
  className?: string;

dtsPropsFor.Progress:
/** Current amount. Clamped into 0..max when rendered. */
  value: number;
  /** Default: 100. */
  max?: number;
  /** Accessible name (aria-label). NOT visible text - the bar draws no caption. */
  label?: string;
  className?: string;

dtsPropsFor.Segmented:
/** Accessible group label for the radio group. */
  label: string;
  /** The currently selected option's value. */
  value: string;
  options: ReadonlyArray<{ value: string; label: string }>;
  onChange: (value: string) => void;
  className?: string;

dtsPropsFor.Sheet:
/** Nothing renders when false. */
  open: boolean;
  /** Called on Escape and on backdrop tap. There is no visible close button. */
  onClose: () => void;
  /** Bold heading above the content; omit it and the header disappears. */
  title?: string;
  children: React.ReactNode;
  className?: string;

dtsPropsFor.ToggleRow:
label: string;
  checked: boolean;
  onChange: (checked: boolean) => void;
  /** Second line of muted text under the label. */
  description?: string;
  className?: string;

dtsPropsFor.LineChart:
/** X axis in order. A null value draws a gap instead of interpolating. */
  points: Array<{ label: string; value: number | null }>;
  /** Required - the SVG's accessible name. */
  ariaLabel: string;
  /** Optional dashed second series (e.g. a rolling mean). Same length as points. */
  overlay?: Array<number | null>;
  /** Formats the axis tick labels. Defaults to an auto-precision number. */
  formatValue?: (value: number) => string;
  className?: string;

dtsPropsFor.ScreenHeader:
title: string;
  subtitle?: string;
  /** Shows the settings link on the right. Default: false. */
  showSettings?: boolean;
